T("losetup","اتصال image به loop device","پیش‌فرض سیستم","losetup [OPTIONS]","LOOP=$(sudo losetup --find --show --read-only --partscan evidence.img)\necho \"$LOOP\"\nlsblk \"$LOOP\"\nsudo losetup -d \"$LOOP\"","--find=آزاد|--show=نمایش|--read-only=فقط‌خواندنی|--partscan=پارتیشن|-d=detach|-a=فهرست"),
T("kpartx","ساخت map پارتیشن‌های image","sudo apt install kpartx","kpartx [OPTIONS] DEVICE","sudo kpartx -av evidence.img\nls -l /dev/mapper/loop*p*\nsudo mount -o ro /dev/mapper/loop0p1 /mnt/evidence\nsudo umount /mnt/evidence && sudo kpartx -dv evidence.img","-a=افزودن|-d=حذف|-v=جزئیات|-r=فقط‌خواندنی|-s=sync"),
T("ddrescue","تصویربرداری مقاوم از رسانه معیوب","sudo apt install gddrescue","ddrescue [OPTIONS] INFILE OUTFILE MAPFILE","sudo ddrescue -f -n /dev/sdX evidence.img evidence.map\nsudo ddrescue -d -r3 /dev/sdX evidence.img evidence.map\nsha256sum evidence.img > evidence.img.sha256\nddrescueview evidence.map","-n=عبور اول بدون retry|-d=direct I/O|-r=retry|-f=بازنویسی output|-R=معکوس|-s=اندازه|MAPFILE=ادامه‌پذیری"),
T("testdisk","بازیابی پارتیشن و فایل‌سیستم","sudo apt install testdisk","testdisk [OPTIONS] [IMAGE]","testdisk /log evidence.img\n# Analyse → Quick Search → Deeper Search → List\ntestdisk /list evidence.img","/log=ثبت|/list=فهرست|Analyse=تحلیل|Quick Search=جست‌وجوی سریع|Deeper Search=عمیق|List=فایل‌ها"),
T("fdisk","بررسی جدول پارتیشن","پیش‌فرض سیستم","fdisk [OPTIONS] DEVICE","sudo fdisk -l evidence.img\nsudo fdisk -l -o Device,Start,End,Sectors,Size,Type /dev/loop0\nfdisk -x evidence.img","-l=فهرست|-o=ستون|-x=جزئیات|-u=واحد sector|-b=sector size|p=چاپ داخل interactive"),
T("parted","بررسی GPT/MBR و offset","پیش‌فرض سیستم","parted [OPTIONS] DEVICE [COMMAND]","sudo parted -s evidence.img unit s print\nsudo parted /dev/loop0 print free\nsudo parted -m evidence.img unit B print > partitions.txt","-s=script|-m=machine|unit s=sector|print=جدول|print free=فضای آزاد|align-check=alignment"),
T("gdisk","بررسی و بازیابی GPT","sudo apt install gdisk","gdisk [OPTIONS] DEVICE","sudo gdisk -l evidence.img\nsudo sgdisk -p evidence.img\nsudo sgdisk -v evidence.img\nsudo sgdisk --backup=gpt.bin /dev/sdX","gdisk -l=فهرست|sgdisk -p=چاپ|sgdisk -v=verify|--backup=پشتیبان GPT|--load-backup=بازگردانی"),
T("cryptsetup","مدیریت LUKS در رسانه خودتان","sudo apt install cryptsetup","cryptsetup ACTION [OPTIONS] DEVICE","sudo cryptsetup luksDump encrypted.img\nsudo cryptsetup luksOpen --readonly encrypted.img evidence_crypt\nsudo mount -o ro /dev/mapper/evidence_crypt /mnt/evidence\nsudo umount /mnt/evidence && sudo cryptsetup close evidence_crypt","luksDump=header|luksOpen=بازکردن|close=بستن|status=وضعیت|--readonly=فقط‌خواندنی|luksHeaderBackup=پشتیبان header"),
