T("cpio","آرشیو بر پایه فهرست فایل","پیش‌فرض سیستم","cpio [OPTIONS]","find evidence -type f -print0 | cpio -0 -ov --format=newc > evidence.cpio\ncpio -itv < evidence.cpio\nmkdir restored && cd restored && cpio -idmv --no-absolute-filenames < ../evidence.cpio","-o=ساخت|-i=استخراج|-t=فهرست|-0=NUL|-v=جزئیات|--format=newc=قالب|--no-absolute-filenames=امن"),
T("pax","آرشیو قابل‌حمل POSIX","sudo apt install pax","pax [OPTIONS] [FILES]","pax -w -x ustar evidence > evidence.pax\npax -f evidence.pax\nmkdir restored && cd restored && pax -r -s ',^/,,' -f ../evidence.pax","-w=نوشتن|-r=خواندن|-f=فایل|-x=قالب|-s=تغییر مسیر|-v=جزئیات"),
T("zstd","فشرده‌سازی سریع و بررسی‌پذیر","sudo apt install zstd","zstd [OPTIONS] FILE","zstd -19 -T0 evidence.tar -o evidence.tar.zst\nzstd --test evidence.tar.zst\nzstd -d evidence.tar.zst -o restored.tar\nzstd --list evidence.tar.zst","-d=بازکردن|-T0=همه CPU|-19=سطح|--test=بررسی|--list=اطلاعات|--rm=حذف منبع"),
T("7z","آرشیو چندقالب و رمزگذاری AES","sudo apt install 7zip","7z COMMAND [OPTIONS] ARCHIVE [FILES]","7z a -t7z -mhe=on archive.7z evidence/\n7z l -slt archive.7z\n7z t archive.7z\n7z x archive.7z -orestored -spf-","a=افزودن|l=فهرست|t=آزمون|x=استخراج|-mhe=رمز نام‌ها|-o=مقصد|-spf-=مسیر نسبی"),
T("dar","آرشیو دیسکی چندبخشی","sudo apt install dar","dar [OPTIONS]","dar -c backup/evidence -R evidence -z\ndar -l backup/evidence\ndar -t backup/evidence\ndar -x backup/evidence -R restored","-c=ساخت|-l=فهرست|-t=آزمون|-x=استخراج|-R=ریشه|-z=فشرده|-s=اندازه slice"),
