T("ntpq","پرس‌وجوی daemon NTP","sudo apt install ntpsec","ntpq [OPTIONS] [COMMAND]","ntpq -pn\nntpq -c rv\nntpq -c associations\nntpq -c 'mrulist limited=20' > ntp-mru.txt","-p=peer|-n=بدون DNS|-c=فرمان|rv=متغیرها|associations=انجمن|mrulist=کلاینت‌ها"),
T("ntpdate","اندازه‌گیری offset بدون تنظیم","sudo apt install ntpsec-ntpdate","ntpdate [OPTIONS] SERVER","ntpdate -q time.example.test\nntpdate -q -u time.example.test | tee offset.txt\nntpdate -d time.example.test\ntimeout 10s ntpdate -q time.example.test","-q=query|-u=پورت unprivileged|-d=debug|-v=نسخه|-t=timeout|-s=syslog","برای جلوگیری از پرش زمان، نمونه‌ها فقط query هستند."),
