def card(t, section_id, index, prev_id, next_id):
    rows=''.join(f'<tr><td dir="ltr"><code>{escape(k.strip())}</code></td><td>{escape(v.strip())}</td></tr>' for k,v in (p.split('=',1) for p in t['flags'].split('|')))
    note=f'<div class="warn">⚠️ {escape(t["note"])}</div>' if t['note'] else ''
    risk_label, risk_class = risk_map[section_id]
    level = "مقدماتی" if index <= 130 else ("میانی" if index <= 347 else "پیشرفته")
    run_guidance = {
        "risk-safe": "از ورودی محلی یا حالت فقط‌خواندنی شروع کنید و پیش از پردازش بعدی، قالب خروجی را بررسی کنید.",
        "risk-active": "دامنه، نرخ و timeout را محدود کنید؛ فقط روی دارایی ثبت‌شده در مجوز اجرا کنید.",
        "risk-lab": "فقط در لابراتوار ایزوله یا CTF با حساب آزمایشی اجرا کنید و snapshot بازگشت داشته باشید."
    }[risk_class]
    guidance = f'''<div class="tool-guidance"><p><b>روش پیشنهادی:</b> پیش از اجرای <code dir="ltr">{escape(t['name'])}</code> نسخه و راهنمای داخلی را ببینید؛ سپس مثال را با هدف آزمایشگاهی جایگزین و ابتدا کم‌خطرترین گزینه را اجرا کنید. {run_guidance}</p><p><b>خروجی و اتصال:</b> stdout را با <code dir="ltr">tee</code> ذخیره، stderr و exit code را جدا ثبت و نتیجه را پیش از دادن به ابزار بعدی اعتبارسنجی کنید. فایل شاهد را هش کنید و فرمان، زمان، محدوده و نسخه ابزار را در گزارش بنویسید.</p></div>'''
    discovery = f'''<details class="more-commands"><summary>فرمان‌های تکمیلی برای کشف مسیر و مستندات</summary><div class="codewrap" dir="ltr"><button class="copybtn" type="button">کپی</button><pre><code>command -v -- {escape(t['name'])} | tee {escape(t['name'])}.path
type -a -- {escape(t['name'])} 2&gt; {escape(t['name'])}.lookup.err
apropos -- {escape(t['name'])} | head -n 20
man -f -- {escape(t['name'])} 2&gt;/dev/null || true</code></pre></div></details>'''
    return f'''<article class="cmd" id="cmd-{escape(t['name'])}" data-search="{escape(t['name']+' '+t['title']+' '+t['flags'])}" data-section="{section_id}" tabindex="-1">
<div class="cmd-head"><h3><code class="cmdname" dir="ltr">{escape(t['name'])}</code><span>{escape(t['title'])}</span></h3><div class="cmd-badges"><span class="badge">{index:03d}</span><span class="badge level">{level}</span><span class="badge {risk_class}">{risk_label}</span><button class="study-toggle" type="button" data-study="cmd-{escape(t['name'])}" aria-label="علامت‌گذاری به‌عنوان مطالعه‌شده" title="مطالعه شد">✓</button><button class="permalink" type="button" data-link="cmd-{escape(t['name'])}" aria-label="کپی پیوند {escape(t['name'])}" title="کپی پیوند">🔗</button></div></div>
<p class="install-line"><b>نصب:</b> <code dir="ltr">{escape(t['install'])}</code></p>
<div class="synwrap"><span class="synlab">SYNTAX</span><code class="syn">{escape(t['syntax'])}</code></div>
<div class="tblwrap"><table><thead><tr><th>زیرفرمان / گزینه</th><th>کاربرد</th></tr></thead><tbody>{rows}</tbody></table></div>
<div class="codewrap" dir="ltr"><button class="copybtn" type="button">کپی</button><pre><code>{code(t['examples'])}</code></pre></div>{guidance}{discovery}{note}
<nav class="command-link" aria-label="حرکت بین ابزارها"><a href="#{prev_id}">→ ابزار قبلی</a><a href="#{section_id}">ابتدای فصل ↑</a><a href="#{next_id}">ابزار بعدی ←</a></nav>
</article>'''

