def explain_command_line(line):
    notes=[]
    stripped=line.strip()
    if stripped.startswith('sudo '): notes.append('با دسترسی مدیریتی اجرا می‌شود؛ دلیل نیاز به privilege را ثبت کنید')
    if '|' in stripped: notes.append('خروجی یک مرحله را به ورودی مرحله بعد می‌دهد؛ pipefail را برای تشخیص شکست فعال کنید')
    if '>>' in stripped: notes.append('خروجی را بدون پاک‌کردن داده قبلی به فایل اضافه می‌کند')
    elif '>' in stripped: notes.append('خروجی را در فایل ثبت می‌کند؛ پیش از بازنویسی مسیر را بررسی کنید')
    if '2>' in stripped or '2>&1' in stripped: notes.append('جریان خطا را نیز ثبت یا ادغام می‌کند')
    if '--' in stripped or ' -' in stripped: notes.append('گزینه‌ها دامنه، قالب یا رفتار فرمان را کنترل می‌کنند')
    if not notes: notes.append('فرمان را با ورودی آزمایشگاهی اجرا و exit code و خروجی آن را ثبت کنید')
    return '؛ '.join(notes)+'.'

